  1	// «Мины»: поле 5 × 5, 3 мины расставляются в start тремя вызовами rng; игрок открывает клетки и забирает выигрыш.
  2	// Спецификация: games/mines/spec.md. Решения: decisions/mines.md (D-001…D-010).
  3	import type { GameModule, Rng, Step } from '../../../platform/sdk/types.ts';
  4	import { GameError } from '../../../platform/sdk/types.ts';
  5	
  6	/** Число клеток поля 5 × 5 (D-002). */
  7	export const CELL_COUNT = 25;
  8	
  9	/** Число мин на поле, фиксировано (D-001). */
 10	export const MINE_COUNT = 3;
 11	
 12	/** Число безопасных клеток: открытие последней завершает раунд (D-006). */
 13	export const SAFE_COUNT = CELL_COUNT - MINE_COUNT;
 14	
 15	/** Доля выплаты после house edge 2 % (D-004). */
 16	export const RTP = 0.98;
 17	
 18	/** Нормализованные параметры раунда: у игры их нет (D-008). */
 19	export type MinesParams = Record<string, never>;
 20	
 21	/** Чем закончился раунд: мина, cashout или открыты все безопасные клетки. */
 22	export type MinesOutcome = 'mine' | 'cashout' | 'cleared';
 23	
 24	/** Состояние раунда (spec, раздел «Результат и выплата»). */
 25	export interface MinesState {
 26	  /** Клетки с минами, по возрастанию. */
 27	  mines: number[];
 28	  /** Открытые безопасные клетки в порядке открытия. */
 29	  revealed: number[];
 30	  /** Клетка с миной, на которой игрок проиграл, иначе `null`. */
 31	  hit: number | null;
 32	  /** Исход раунда, `null` пока раунд открыт. */
 33	  outcome: MinesOutcome | null;
 34	}
 35	
 36	/** Ход игрока (D-007). */
 37	export type MinesAction = { type: 'reveal'; cell: number } | { type: 'cashout' };
 38	
 39	/** Что видит клиент (D-009). Поля `mines`, `hit`, `outcome` есть только после завершения раунда. */
 40	export interface MinesView {
 41	  mineCount: number;
 42	  revealed: number[];
 43	  multiplier: number;
 44	  nextMultiplier: number | null;
 45	  mines?: number[];
 46	  hit?: number | null;
 47	  outcome?: MinesOutcome | null;
 48	}
 49	
 50	function round2(x: number): number {
 51	  return Math.round(x * 100) / 100;
 52	}
 53	
 54	function binom(n: number, k: number): number {
 55	  let r = 1;
 56	  for (let i = 1; i <= k; i++) r = (r * (n - k + i)) / i;
 57	  return r;
 58	}
 59	
 60	/**
 61	 * Множитель после `k` открытых безопасных клеток (D-004):
 62	 * `M(0) = 1` (только для отображения), иначе `round2(0.98 × C(25, k) / C(22, k))`.
 63	 */
 64	export function multiplier(k: number): number {
 65	  if (k <= 0) return 1;
 66	  return round2((RTP * binom(CELL_COUNT, k)) / binom(SAFE_COUNT, k));
 67	}
 68	
 69	/** Расстановка мин частичной тасовкой Фишера — Йетса: ровно 3 вызова rng (D-003). */
 70	function placeMines(rng: Rng): number[] {
 71	  const c = Array.from({ length: CELL_COUNT }, (_, i) => i);
 72	  for (let i = 0; i < MINE_COUNT; i++) {
 73	    const j = i + Math.floor(rng.next() * (CELL_COUNT - i));
 74	    const t = c[i] as number;
 75	    c[i] = c[j] as number;
 76	    c[j] = t;
 77	  }
 78	  return c.slice(0, MINE_COUNT).sort((a, b) => a - b);
 79	}
 80	
 81	function invalidAction(message: string): never {
 82	  throw new GameError('INVALID_ACTION', message);
 83	}
 84	
 85	/** Проверяет ход до любых изменений; возвращает нормализованное действие. */
 86	function parseAction(action: unknown, state: MinesState): MinesAction {
 87	  if (typeof action !== 'object' || action === null || Array.isArray(action)) {
 88	    invalidAction('Ход должен быть объектом { type, cell }');
 89	  }
 90	  const type = (action as { type?: unknown }).type;
 91	  if (type === 'cashout') {
 92	    if (state.revealed.length < 1) invalidAction('Забрать выигрыш можно после первой открытой клетки');
 93	    return { type: 'cashout' };
 94	  }
 95	  if (type === 'reveal') {
 96	    const cell = (action as { cell?: unknown }).cell;
 97	    if (typeof cell !== 'number' || !Number.isInteger(cell) || cell < 0 || cell >= CELL_COUNT) {
 98	      invalidAction('cell должен быть целым числом от 0 до 24');
 99	    }
100	    if (state.revealed.includes(cell)) invalidAction('Клетка уже открыта');
101	    return { type: 'reveal', cell };
102	  }
103	  return invalidAction('Неизвестный тип хода');
104	}
105	
106	/**
107	 * Серверный модуль «Мин».
108	 *
109	 * - `validateParams(params)` — `{}` для объекта или `undefined`, лишние поля отбрасываются;
110	 *   `null`, массив, строка, число → `GameError('INVALID_PARAMS')` (D-008).
111	 * - `start({ rng })` — 3 вызова `rng.next()`, расстановка мин, шаг `continue` (D-003).
112	 * - `action({ bet, state, action })` — `reveal`/`cashout`, rng не используется, `state` не меняется (D-005…D-007).
113	 * - `publicView(state, finished)` — до конца раунда без `mines`/`hit`/`outcome` (D-009).
114	 */
115	const game: GameModule<MinesParams, MinesState, unknown> = {
116	  id: 'mines',
117	
118	  validateParams(params: unknown): MinesParams {
119	    if (params === undefined) return {};
120	    if (typeof params !== 'object' || params === null || Array.isArray(params)) {
121	      throw new GameError('INVALID_PARAMS', 'Параметры должны быть объектом');
122	    }
123	    return {};
124	  },
125	
126	  start({ params, rng }: { bet: number; params: MinesParams; rng: Rng }): Step<MinesState> {
127	    // Всё, что может упасть, — до обращения к rng (контракт platform/sdk/types.ts).
128	    game.validateParams(params);
129	    const mines = placeMines(rng);
130	    return { status: 'continue', state: { mines, revealed: [], hit: null, outcome: null } };
131	  },
132	
133	  action({ bet, state, action }: { bet: number; params: MinesParams; state: MinesState; action: unknown; rng: Rng }): Step<MinesState> {
134	    const a = parseAction(action, state);
135	    const mines = state.mines.slice();
136	    if (a.type === 'cashout') {
137	      const revealed = state.revealed.slice();
138	      return {
139	        status: 'finished',
140	        state: { mines, revealed, hit: null, outcome: 'cashout' },
141	        payout: bet * multiplier(revealed.length),
142	      };
143	    }
144	    if (mines.includes(a.cell)) {
145	      return {
146	        status: 'finished',
147	        state: { mines, revealed: state.revealed.slice(), hit: a.cell, outcome: 'mine' },
148	        payout: 0,
149	      };
150	    }
151	    const revealed = [...state.revealed, a.cell];
152	    if (revealed.length >= SAFE_COUNT) {
153	      return {
154	        status: 'finished',
155	        state: { mines, revealed, hit: null, outcome: 'cleared' },
156	        payout: bet * multiplier(revealed.length),
157	      };
158	    }
159	    return { status: 'continue', state: { mines, revealed, hit: null, outcome: null } };
160	  },
161	
162	  publicView(state: MinesState, finished: boolean): MinesView {
163	    const k = state.revealed.length;
164	    const base = { mineCount: MINE_COUNT, revealed: state.revealed.slice(), multiplier: multiplier(k) };
165	    if (!finished) return { ...base, nextMultiplier: multiplier(k + 1) };
166	    return { ...base, nextMultiplier: null, mines: state.mines.slice(), hit: state.hit, outcome: state.outcome };
167	  },
168	};
169	
170	/** Модуль игры `mines` (`GameModule`), который платформа загружает по `manifest.json`. */
171	export default game;
