107	 * Серверный модуль «Мин».
108	 *
109	 * - `validateParams(params)` — `{}` для объекта или `undefined`, лишние поля отбрасываются;
110	 *   `null`, массив, строка, число → `GameError('INVALID_PARAMS')` (D-008).
111	 * - `start({ rng })` — 3 вызова `rng.next()`, расстановка мин, шаг `continue` (D-003).
112	 * - `action({ bet, state, action })` — `reveal`/`cashout`, rng не используется, `state` не меняется (D-005…D-007).
113	 * - `publicView(state, finished)` — до конца раунда без `mines`/`hit`/`outcome` (D-009).
114	 */
115	const game: GameModule<MinesParams, MinesState, unknown> = {
116	  id: 'mines',
117	
118	  validateParams(params: unknown): MinesParams {
119	    if (params === undefined) return {};
120	    if (typeof params !== 'object' || params === null || Array.isArray(params)) {
121	      throw new GameError('INVALID_PARAMS', 'Параметры должны быть объектом');
122	    }
123	    return {};
124	  },
125	
126	  start({ params, rng }: { bet: number; params: MinesParams; rng: Rng }): Step<MinesState> {
127	    // Всё, что может упасть, — до обращения к rng (контракт platform/sdk/types.ts).
128	    game.validateParams(params);
129	    const mines = placeMines(rng);
130	    return { status: 'continue', state: { mines, revealed: [], hit: null, outcome: null } };
131	  },
132	
133	  action({ bet, state, action }: { bet: number; params: MinesParams; state: MinesState; action: unknown; rng: Rng }): Step<MinesState> {
134	    const a = parseAction(action, state);
135	    const mines = state.mines.slice();
136	    if (a.type === 'cashout') {
137	      const revealed = state.revealed.slice();
138	      return {
139	        status: 'finished',
140	        state: { mines, revealed, hit: null, outcome: 'cashout' },
141	        payout: bet * multiplier(revealed.length),
142	      };
143	    }
144	    if (mines.includes(a.cell)) {
145	      return {
146	        status: 'finished',
147	        state: { mines, revealed: state.revealed.slice(), hit: a.cell, outcome: 'mine' },
148	        payout: 0,
149	      };
150	    }
151	    const revealed = [...state.revealed, a.cell];
152	    if (revealed.length >= SAFE_COUNT) {
153	      return {
154	        status: 'finished',
155	        state: { mines, revealed, hit: null, outcome: 'cleared' },
156	        payout: bet * multiplier(revealed.length),
157	      };
158	    }
159	    return { status: 'continue', state: { mines, revealed, hit: null, outcome: null } };
160	  },
161	
162	  publicView(state: MinesState, finished: boolean): MinesView {
163	    const k = state.revealed.length;
164	    const base = { mineCount: MINE_COUNT, revealed: state.revealed.slice(), multiplier: multiplier(k) };
165	    if (!finished) return { ...base, nextMultiplier: multiplier(k + 1) };
166	    return { ...base, nextMultiplier: null, mines: state.mines.slice(), hit: state.hit, outcome: state.outcome };
167	  },
168	};
